import{_ as e,o as a,c as r,a2 as d}from"./chunks/framework.CmvPqeTF.js";const b=JSON.parse('{"title":"HTTPS 证书管理","description":"","frontmatter":{},"headers":[],"relativePath":"guide/certificates.md","filePath":"guide/certificates.md","lastUpdated":1791351888000}'),l={name:"guide/certificates.md"};function o(h,t,i,s,c,n){return a(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="https-证书管理" tabindex="-1">HTTPS 证书管理 <a class="header-anchor" href="#https-证书管理" aria-label="Permalink to &quot;HTTPS 证书管理&quot;">​</a></h1><p>左条的「证书管理」图标（盾牌）打开证书面板：通过 SSH 在<strong>远程服务器</strong>上驱动 <a href="https://github.com/acmesh-official/acme.sh" target="_blank" rel="noreferrer">acme.sh</a>，完成 Let&#39;s Encrypt 等 CA 证书的签发、部署与自动续签。vShell 本地只保存「证书任务」，实际证书由服务器上的 acme.sh 管理。</p><blockquote><p>验证方式为 <strong>DNS-01</strong>：需要域名 DNS 服务商的 API 凭据（阿里云 / DNSPod / 腾讯云 / Cloudflare，或自定义 acme.sh 插件），无需开放 80 / 443 端口，也支持泛域名。</p></blockquote><hr><h2 id="_1-面板结构" tabindex="-1">1. 面板结构 <a class="header-anchor" href="#_1-面板结构" aria-label="Permalink to &quot;1. 面板结构&quot;">​</a></h2><p>任务<strong>按连接（服务器）分组</strong>折叠展示，每条任务显示：</p><ul><li>状态标签：<strong>待签发 / 执行中 / 已签发 / 失败</strong>（失败时附最近一次错误信息）</li><li>域名（主域名 + 附加域名）</li><li>到期标签：剩余 N 天 / 即将到期（30 天内，黄色）/ 已过期 / 服务器上不存在</li><li>测试模式的任务带黄色 <code>staging</code> 标签</li></ul><p><strong>到期与续签是两个时间</strong>：证书真实到期时间（「剩余 N 天」）与 acme.sh 的自动续签倒计时（「N 天后自动续签」）分开显示——acme.sh 会提前续签（约在证书有效期的前 1/3 窗口内），因此续签倒计时总是短于到期倒计时，二者不可混为一谈。</p><table tabindex="0"><thead><tr><th>操作</th><th>位置</th><th>说明</th></tr></thead><tbody><tr><td>刷新远端状态</td><td>分组标题右侧</td><td>重新读取服务器 <code>acme.sh --list</code>，同步远端实际状态</td></tr><tr><td>立即签发 / 续签</td><td>行内按钮</td><td>待签发任务执行签发，已签发任务执行续签</td></tr><tr><td>日志</td><td>行内按钮</td><td>查看该任务最近一次操作的完整日志</td></tr><tr><td>编辑</td><td>行内按钮</td><td>修改域名 / DNS 凭据 / 部署配置</td></tr><tr><td>从服务器移除</td><td>行内按钮</td><td>让服务器上的 acme.sh 移除该证书，并删除本地任务</td></tr><tr><td>删除任务</td><td>行内按钮</td><td>仅删除本地任务记录，服务器上的 acme.sh 仍继续管理该证书</td></tr></tbody></table><h2 id="_2-签发证书向导" tabindex="-1">2. 签发证书向导 <a class="header-anchor" href="#_2-签发证书向导" aria-label="Permalink to &quot;2. 签发证书向导&quot;">​</a></h2><p>点击「签发证书」进入四步向导：</p><h3 id="第-1-步-·-服务器" tabindex="-1">第 1 步 · 服务器 <a class="header-anchor" href="#第-1-步-·-服务器" aria-label="Permalink to &quot;第 1 步 · 服务器&quot;">​</a></h3><ul><li>选择目标连接（给哪台服务器签证书）</li><li><strong>ACME 账户邮箱</strong>：首次在该服务器安装 acme.sh 时用于注册 CA 账户，输入后会被记住，之后不再填写</li><li>打开向导时自动检测服务器环境：acme.sh 是否已安装、自动续签 cron 是否存在、curl 是否可用；未安装时可在本步一键安装</li></ul><h3 id="第-2-步-·-域名与-dns" tabindex="-1">第 2 步 · 域名与 DNS <a class="header-anchor" href="#第-2-步-·-域名与-dns" aria-label="Permalink to &quot;第 2 步 · 域名与 DNS&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>任务名称</td><td>默认取主域名</td></tr><tr><td>主域名</td><td>如 <code>example.com</code></td></tr><tr><td>附加域名</td><td>每行一个，支持泛域名（如 <code>*.example.com</code>）</td></tr><tr><td>DNS 服务商</td><td>阿里云 / DNSPod（传统 Token）/ 腾讯云（SecretId + SecretKey）/ Cloudflare / 自定义</td></tr><tr><td>凭据变量</td><td>按所选服务商动态渲染表单；选「自定义」需填 acme.sh 插件名（<code>dns_xx</code>，见 acme.sh dnsapi 文档）与凭据键值对</td></tr></tbody></table><h3 id="第-3-步-·-部署" tabindex="-1">第 3 步 · 部署 <a class="header-anchor" href="#第-3-步-·-部署" aria-label="Permalink to &quot;第 3 步 · 部署&quot;">​</a></h3><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td>部署证书到服务器路径</td><td>开启后填写证书目录、私钥文件名、证书链文件名，签发成功后自动拷贝部署</td></tr><tr><td>重载命令</td><td>Nginx / Apache / Caddy 预设或自定义（如 <code>nginx -s reload</code>）；「不重载」则跳过</td></tr><tr><td>高级选项</td><td>密钥类型（ECC P-256 默认 / RSA 2048）、DNS 传播等待秒数（默认 120）、<strong>测试模式</strong></td></tr></tbody></table><blockquote><p><strong>测试模式（staging）</strong>：使用 CA 测试环境签发，用于首次跑通流程，避免触发 Let&#39;s Encrypt 正式环境的频率限制；跑通后关闭测试模式，重新签发正式证书。</p></blockquote><h3 id="第-4-步-·-签发" tabindex="-1">第 4 步 · 签发 <a class="header-anchor" href="#第-4-步-·-签发" aria-label="Permalink to &quot;第 4 步 · 签发&quot;">​</a></h3><p>自动按阶段执行并实时输出日志：<strong>检测环境 → 安装 acme.sh（如需）→ 申请证书 → 部署证书 → 检测定时任务 → 完成</strong>。日志区固定高度内滚动，右上角可一键复制；失败后可直接重试。</p><h2 id="_3-凭据安全" tabindex="-1">3. 凭据安全 <a class="header-anchor" href="#_3-凭据安全" aria-label="Permalink to &quot;3. 凭据安全&quot;">​</a></h2><ul><li>DNS API 凭据以 AES-256-GCM 加密入库，<strong>永不明文回传前端</strong>；需要核对已存凭据时走专门的「查看已存凭据」入口</li><li>签发时凭据经 SFTP 写入服务器上的<strong>临时 env 文件</strong>（权限 600，签发命令结束时自删），不会进入 shell 历史</li><li>详见<a href="./../dev/storage-crypto.html">数据存储与加密</a></li></ul><h2 id="_4-续签机制" tabindex="-1">4. 续签机制 <a class="header-anchor" href="#_4-续签机制" aria-label="Permalink to &quot;4. 续签机制&quot;">​</a></h2><ul><li>续签由<strong>服务器上的 cron 每日执行</strong>，无需保持 vShell 在线</li><li>vShell 内手动续签刻意走 <code>--issue --force</code> 而非 <code>--renew</code>：<code>--renew</code> 会重放服务器上旧配置里的插件与凭据，在 vShell 里更换过 DNS 服务商或凭据后不会生效；<code>--issue --force</code> 则始终使用<strong>当前任务保存的凭据</strong></li><li>在 vShell 中更换 DNS 服务商 / 凭据后，执行一次「立即续签」即可让服务器上的续签配置同步为新凭据</li></ul><h2 id="_5-日志" tabindex="-1">5. 日志 <a class="header-anchor" href="#_5-日志" aria-label="Permalink to &quot;5. 日志&quot;">​</a></h2><ul><li>每次操作的日志<strong>持久化保存在本地任务上</strong>，重开日志窗口不丢</li><li>每次操作开始会先<strong>清空服务器侧 acme.sh 日志</strong>再执行，日志窗口看到的即是本轮输出</li><li>也可通过「服务器 acme.sh 日志」入口直接查看服务器上 acme.sh 自身的日志文件</li></ul><h2 id="_6-删除与移除的两种语义" tabindex="-1">6. 删除与移除的两种语义 <a class="header-anchor" href="#_6-删除与移除的两种语义" aria-label="Permalink to &quot;6. 删除与移除的两种语义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>操作</th><th>本地任务</th><th>服务器证书</th></tr></thead><tbody><tr><td>删除任务</td><td>删除</td><td>保留，acme.sh 仍继续管理并自动续签</td></tr><tr><td>从服务器移除</td><td>删除</td><td>acme.sh 移除该证书（停止续签）；<strong>已部署的证书文件保留</strong></td></tr></tbody></table><h2 id="_7-当前边界-如实说明" tabindex="-1">7. 当前边界（如实说明） <a class="header-anchor" href="#_7-当前边界-如实说明" aria-label="Permalink to &quot;7. 当前边界（如实说明）&quot;">​</a></h2><ul><li>仅支持 DNS-01 验证（无 HTTP / 文件验证）</li><li>目标服务器需为类 Unix 环境且可安装 acme.sh（依赖 curl 与 cron）</li><li>vShell 中没有签发过程的「取消」按钮；应用重启后，上次被中断的「执行中」任务会自动复位，可重新发起</li></ul><hr><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./connections.html">连接与分组管理</a> —— 证书任务挂在服务器连接上</li><li><a href="./../dev/storage-crypto.html">数据存储与加密</a> —— DNS 凭据的加密存储</li><li><a href="./../dev/architecture.html">架构总览</a> —— <code>internal/cert</code> 编排器实现</li></ul>',33)])])}const m=e(l,[["render",o]]);export{b as __pageData,m as default};
